PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
DROP TABLE IF EXISTS product_purchase_details;
DROP TABLE IF EXISTS product_information;
DROP TABLE IF EXISTS product_category;

CREATE TABLE product_category (
  category_id INTEGER PRIMARY KEY,
  category_name TEXT,
  status INTEGER NOT NULL
);

CREATE TABLE product_information (
  id INTEGER PRIMARY KEY,
  product_id TEXT NOT NULL UNIQUE,
  category_id INTEGER NOT NULL,
  product_name TEXT NOT NULL,
  generic_name TEXT NOT NULL,
  strength TEXT NOT NULL,
  box_size TEXT NOT NULL,
  product_location TEXT NOT NULL,
  price NUMERIC NOT NULL DEFAULT 0.00,
  b_price NUMERIC NOT NULL DEFAULT 0.00,
  m_b_price NUMERIC NOT NULL DEFAULT 0.00,
  caution_level TEXT DEFAULT 'normal' CHECK (caution_level IN ('low','normal','high')),
  manufacturer_price NUMERIC,
  unit TEXT,
  product_details TEXT,
  image TEXT,
  status INTEGER NOT NULL,
  FOREIGN KEY (category_id) REFERENCES product_category(category_id) ON DELETE RESTRICT ON UPDATE CASCADE
);

CREATE TABLE product_purchase_details (
  id INTEGER PRIMARY KEY,
  product_id TEXT NOT NULL,
  quantity REAL,
  box_qty REAL,
  unit_rate NUMERIC,
  rate NUMERIC,
  old_mprice NUMERIC,
  mrp NUMERIC,
  total_amount NUMERIC,
  discount NUMERIC,
  single_vat NUMERIC,
  caution_level TEXT NOT NULL DEFAULT 'normal' CHECK (caution_level IN ('low','normal','high')),
  expire_date TEXT,
  status INTEGER NOT NULL,
  FOREIGN KEY (product_id) REFERENCES product_information(product_id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_category_status ON product_category(status);
CREATE INDEX IF NOT EXISTS idx_info_category_id ON product_information(category_id);
CREATE INDEX IF NOT EXISTS idx_info_caution ON product_information(caution_level);
CREATE INDEX IF NOT EXISTS idx_info_status ON product_information(status);
CREATE INDEX IF NOT EXISTS idx_purchase_product_id ON product_purchase_details(product_id);
CREATE INDEX IF NOT EXISTS idx_purchase_caution ON product_purchase_details(caution_level);
CREATE INDEX IF NOT EXISTS idx_purchase_expire ON product_purchase_details(expire_date);
CREATE INDEX IF NOT EXISTS idx_purchase_status ON product_purchase_details(status);









COMMIT;
